const body = $input.first().json.body;
const link = body.productUrl || body.link;
const origemManual = (body.origem || '').toLowerCase();
let origem = origemManual;

if (!link) {
  throw new Error('Nenhuma URL de produto foi informada (campo productUrl ausente).');
}

if (!origem) {
  if (link.includes('mercadolivre') || link.includes('mercadolibre')) origem = 'mercadolivre';
  else if (link.includes('amazon')) origem = 'amazon';
  else if (link.includes('shopee')) origem = 'shopee';
  else throw new Error('Origem não reconhecida. Informe origem: mercadolivre, amazon ou shopee');
}

const atores = {
  mercadolivre: 'leadercorp~mercadolivre-scraper-br-pro',
  amazon: 'junglee~amazon-crawler',
  shopee: 'gio21~shopee-scraper'
};

const ator = atores[origem];
if (!ator) throw new Error('Plataforma não suportada: ' + origem);

return [{
  json: {
    link,
    origem,
    ator,
    accountId: body.accountId,
    userId: body.userId,
    markupPct: body.markupPct,
    defaultQty: body.defaultQty
  }
}];

const link = $('Code - Detecta Plataforma1').item.json.link;
const origem = $('Code - Detecta Plataforma1').item.json.origem;

let body = {};

if (origem === 'mercadolivre') {
  body = {
    startUrls: [{ url: link }],
    proxyConfiguration: {
      useApifyProxy: true,
      apifyProxyGroups: ['RESIDENTIAL'],
      apifyProxyCountry: 'BR'
    }
  };
} else if (origem === 'amazon') {
  body = {
    categoryOrProductUrls: [{ url: link }],
    maxItems: 1,
    proxyConfiguration: {
      useApifyProxy: true,
      apifyProxyGroups: ['RESIDENTIAL'],
      apifyProxyCountry: 'BR'
    }
  };
} else if (origem === 'shopee') {
  const match = link.match(/i\.(\d+)\.(\d+)/);
  if (!match) throw new Error('Link Shopee inválido — formato esperado: ...i.SHOPID.ITEMID');
  body = {
    shopId: parseInt(match[1], 10),
    itemId: parseInt(match[2], 10),
    country: 'BR'
  };
}

return [{
  json: {
    body,
    ator: $('Code - Detecta Plataforma1').item.json.ator,
    link,
    origem
  }
}];

const items = $input.all();
const detect = $('Code - Detecta Plataforma1').item.json;

const MARKUP_PCT = Number(detect.markupPct) > 0 ? Number(detect.markupPct) : 40;
const DEFAULT_QTY = Number(detect.defaultQty) > 0 ? Number(detect.defaultQty) : 5;
const MAX_PICTURES = 10;
const TITLE_MAX_LEN = 60;

function sanitizarTexto(texto) {
  if (!texto) return '';
  let t = String(texto);
  t = t.replace(/<[^>]+>/g, ' ');
  t = t.replace(/\bhttps?:\/\/\S+/gi, ' ');
  t = t.replace(/\bwww\.\S+/gi, ' ');
  t = t.replace(/[\w.+-]+@[\w-]+\.[\w.-]+/gi, ' ');
  t = t.replace(/\(?\d{2}\)?[\s.-]?9?\d{4}[\s.-]?\d{4}\b/g, ' ');
  t = t.replace(/\b(whatsapp|instagram|facebook|telegram|tiktok)\b/gi, ' ');
  t = t.replace(/\bamazon\b/gi, ' ');
  t = t.replace(/[™®©]/g, '');
  return t.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

function truncarTitulo(titulo, max) {
  if (titulo.length <= max) return titulo;
  let cortado = titulo.slice(0, max);
  const lastSpace = cortado.lastIndexOf(' ');
  if (lastSpace > 0) cortado = cortado.slice(0, lastSpace);
  return cortado.trim();
}

function gerarDescricaoFallback(a, titleFull, brand) {
  const attrs = a.attributes || [];
  const linhas = [titleFull];
  if (brand) linhas.push(`Marca: ${brand}`);
  const ignorar = /ranking|asin|avalia|ref\.?\s*id/i;
  const atributosUteis = attrs.filter(at => at.key && at.value && !ignorar.test(at.key));
  if (atributosUteis.length) {
    linhas.push('', 'Características:');
    for (const at of atributosUteis) linhas.push(`- ${at.key}: ${at.value}`);
  }
  return linhas.join('\n').trim();
}

return items.map(item => {
  const a = item.json;
  const avisos = [];
  const titleFull = sanitizarTexto((a.title || '').trim());
  const title = truncarTitulo(titleFull, TITLE_MAX_LEN);
  const precoBase = a.price?.value ?? 0;
  const precoFinal = Math.round(precoBase * (1 + MARKUP_PCT / 100) * 100) / 100;
  if (!precoFinal || precoFinal <= 0) avisos.push('Preço da origem não encontrado ou zerado.');

  let brand = sanitizarTexto((a.brand || '').replace(/^Marca:\s*/i, '').trim());
  let description = a.description || '';
  if (!description && a.aPlusContent?.rawText) description = a.aPlusContent.rawText.replace(/^Descrição do produto\s*/, '').trim();
  if (!description && Array.isArray(a.features) && a.features.length) description = a.features.join('\n');
  if (!description) description = gerarDescricaoFallback(a, titleFull, brand);
  description = sanitizarTexto(description);

  const estoqueReal = Number(a.availability?.quantity ?? a.stock ?? a.quantity ?? a.available_quantity);
  const available_quantity = Number.isFinite(estoqueReal) && estoqueReal > 0 ? estoqueReal : DEFAULT_QTY;

  const imagensBrutas = a.highResolutionImages || a.galleryThumbnails || [];
  const pictures = [...new Set(imagensBrutas.filter(Boolean))].slice(0, MAX_PICTURES).map(url => ({ source: url }));
  if (!pictures.length) avisos.push('Nenhuma imagem encontrada — o ML exige ao menos 1 foto.');

  return {
    json: {
      title,
      title_full: titleFull,
      price: precoFinal,
      brand,
      description,
      pictures,
      asin: a.asin || null,
      available_quantity,
      _amazon_raw_attributes: a.attributes || [],
      _avisos: avisos,
      _origem: detect.origem
    }
  };
});

const raw = $input.first().json;
const cat = Array.isArray(raw) ? raw[0] : raw;
if (!cat?.category_id) throw new Error('Prever Categoria ML1 não retornou category_id.');
return [{ json: { category_id: cat.category_id, category_name: cat.category_name || '' } }];

const RELEVANCE_THRESHOLD = 2;
const INCLUIR_ATRIBUTOS_EXTRAS = false;
const PERMITIR_INFERENCIA_POR_TEXTO = true;
const ASSUMIR_PRODUTO_NOVO = true;

const NUNCA_INVENTAR = new Set([
  'PRODUCT_CHEMICAL_FEATURES', 'FOODS_AND_DRINKS', 'MEDICINES', 'BATTERIES_FEATURES',
  'ADDITIONAL_INFO_REQUIRED', 'EXCLUDED_PLATFORMS', 'HAZMAT_TRANSPORTABILITY',
  'PRODUCT_FEATURES', 'SHIPMENT_PACKING', 'DESCRIPTIVE_TAGS', 'VERTICAL_TAGS',
  'LIMITED_MARKETPLACE_VISIBILITY_REASONS', 'SEARCH_ENHANCEMENT_FIELDS', 'CATALOG_TITLE',
  'PRODUCT_DATA_SOURCE', 'PACKAGE_DATA_SOURCE', 'SELLER_PACKAGE_DATA_SOURCE', 'AGID',
  'VALUE_ADDED_TAX', 'IMPORT_DUTY', 'SYI_PYMES_ID', 'IS_FLAMMABLE', 'IS_NEW_OFFER',
  'HAS_COMPATIBILITIES', 'IS_SUITABLE_FOR_SHIPMENT', 'WITH_POSITIVE_IMPACT',
  'WITH_EXPIRATION_DATE'
]);

const SINONIMOS = {
  BRAND: ['marca', 'brand', 'fabricante'],
  MODEL: ['modelo', 'model', 'numero de modelo', 'número de modelo', 'referencia do fabricante', 'referência do fabricante'],
  MPN: ['mpn', 'referencia do fabricante', 'referência do fabricante', 'numero do fabricante', 'número do fabricante', 'part number'],
  SELLER_SKU: ['referencia do fabricante', 'referência do fabricante', 'sku', 'codigo do produto', 'código do produto'],
  GTIN: ['gtin', 'ean', 'upc', 'codigo de barras', 'código de barras'],
  FRAGRANCE: ['fragrancia', 'fragrância', 'aroma', 'perfume', 'cheiro'],
  MAIN_AROMA: ['aroma', 'fragrancia', 'fragrância'],
  LINE: ['linha', 'colecao', 'coleção', 'line'],
  PACKAGING_TYPE: ['tipo de embalagem', 'embalagem', 'packaging'],
  DETERGENT_FORMAT: ['formato', 'tipo', 'forma'],
  NET_WEIGHT: ['peso liquido', 'peso líquido', 'peso do item', 'peso', 'net weight'],
  NET_VOLUME: ['volume', 'volume liquido', 'volume líquido', 'capacidade', 'litros', 'litro'],
  COLOR: ['cor', 'color', 'colour'],
  MAIN_COLOR: ['cor', 'color', 'colour'],
  MATERIAL: ['material', 'composicao', 'composição'],
  SELLER_PACKAGE_WEIGHT: ['peso', 'weight', 'dimensoes do produto', 'dimensões do produto'],
  SELLER_PACKAGE_LENGTH: ['comprimento', 'length', 'dimensoes do produto', 'dimensões do produto'],
  SELLER_PACKAGE_WIDTH: ['largura', 'width', 'dimensoes do produto', 'dimensões do produto'],
  SELLER_PACKAGE_HEIGHT: ['altura', 'height', 'dimensoes do produto', 'dimensões do produto'],
  PACKAGE_WEIGHT: ['peso', 'dimensoes do produto', 'dimensões do produto'],
  PACKAGE_LENGTH: ['comprimento', 'dimensoes do produto', 'dimensões do produto'],
  PACKAGE_WIDTH: ['largura', 'dimensoes do produto', 'dimensões do produto'],
  PACKAGE_HEIGHT: ['altura', 'dimensoes do produto', 'dimensões do produto'],
  MANUAL_TITLE: ['titulo', 'título', 'nome do produto'],
  SALE_FORMAT: ['formato de venda', 'unidade de venda']
};

const UNIDADE_ALIAS = { kg: 'kg', g: 'g', l: 'l', litro: 'l', litros: 'l', ml: 'ml', m: 'm', cm: 'cm', mm: 'mm' };

function normalizar(str) {
  return String(str || '').toLowerCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

function getNodeJson(nodeName) {
  try { return $(nodeName).first().json; }
  catch (e) { throw new Error('Node "' + nodeName + '" não foi executado nesta run.'); }
}

function isModificavel(attr) {
  if (!attr) return false;
  if (attr.tags?.read_only && !attr.id.startsWith('PACKAGE_') && !attr.id.startsWith('SELLER_PACKAGE_')) return false;
  if (NUNCA_INVENTAR.has(attr.id)) return false;
  return true;
}

function montarNumberUnitPayload(id, parsed) {
  return { id, value_name: parsed.number + ' ' + parsed.unit, value_struct: parsed };
}

function parsePeso(texto) {
  const m = String(texto).match(/(\d+[.,]?\d*)\s*(quilogramas?|kg|gramas?|g)\b/i);
  if (!m) return null;
  let n = parseFloat(m[1].replace(',', '.'));
  if (/quilo|kg/i.test(m[2])) n = Math.round(n * 1000);
  return { number: n, unit: 'g' };
}

function parseVolume(texto) {
  const m = String(texto).match(/(\d+[.,]?\d*)\s*(litros?|l|ml|mililitros?)\b/i);
  if (!m) return null;
  const n = parseFloat(m[1].replace(',', '.'));
  if (/ml|mililitro/i.test(m[2])) return { number: n, unit: 'ml' };
  return { number: n, unit: 'L' };
}

function parseDimensoesCm(texto) {
  const m = String(texto).match(/(\d+[.,]?\d*)\s*x\s*(\d+[.,]?\d*)\s*x\s*(\d+[.,]?\d*)\s*cm/i);
  if (!m) return null;
  const nums = [m[1], m[2], m[3]].map(v => parseFloat(v.replace(',', '.')));
  nums.sort((a, b) => b - a);
  return { length: nums[0], width: nums[1], height: nums[2], unit: 'cm' };
}

function extrairNumberUnitDeTexto(attr, valorTexto) {
  if (!valorTexto) return null;
  const id = attr.id;
  const dims = parseDimensoesCm(valorTexto);
  const peso = parsePeso(valorTexto);
  const volume = parseVolume(valorTexto);

  if (dims && /length|comprimento/i.test(id)) return montarNumberUnitPayload(id, { number: dims.length, unit: 'cm' });
  if (dims && /width|largura/i.test(id)) return montarNumberUnitPayload(id, { number: dims.width, unit: 'cm' });
  if (dims && /height|altura/i.test(id)) return montarNumberUnitPayload(id, { number: dims.height, unit: 'cm' });
  if (peso && /weight|peso/i.test(id)) return montarNumberUnitPayload(id, peso);
  if (volume && /volume/i.test(id)) return montarNumberUnitPayload(id, volume);

  const m = String(valorTexto).trim().match(/^(-?\d+(?:[.,]\d+)?)\s*([a-zA-Zçãáéíóúâêô°]+)?$/);
  if (!m) return null;
  const number = parseFloat(m[1].replace(',', '.'));
  if (Number.isNaN(number)) return null;
  const unidadeCodigo = m[2] ? (UNIDADE_ALIAS[normalizar(m[2])] || normalizar(m[2])) : null;
  const allowed = attr.allowed_units || attr.unit_values || [];
  if (allowed.length) {
    let match = null;
    if (unidadeCodigo) match = allowed.find(u => normalizar(u.id) === unidadeCodigo || normalizar(u.name) === unidadeCodigo);
    if (!match && !unidadeCodigo && allowed.length === 1) match = allowed[0];
    if (match) return montarNumberUnitPayload(id, { number, unit: match.id });
    return null;
  }
  if (unidadeCodigo) return montarNumberUnitPayload(id, { number, unit: unidadeCodigo });
  return null;
}

const categoria = getNodeJson('Normalizar Categoria ML1');
const categoryId = categoria.category_id;
const categoryName = categoria.category_name;
const todosAtributos = $input.all().map(i => i.json).filter(isModificavel);
const dadosProduto = getNodeJson('Mapear Produto para ML1');
const amazonAttrs = (dadosProduto._amazon_raw_attributes || [])
  .filter(a => a?.key)
  .map(a => ({ ...a, value: String(a.value || '').trim(), _keyNorm: normalizar(a.key) }));

const textoScraping = amazonAttrs.map(a => a.key + ' ' + a.value).join(' ');
const textoProdutoNorm = normalizar([
  dadosProduto.title, dadosProduto.title_full, dadosProduto.description, categoryName, textoScraping
].filter(Boolean).join(' '));

const obrigatorios = todosAtributos.filter(a => a.tags?.required || a.tags?.conditional_required || a.tags?.new_required);

function inferirDeTexto(attr) {
  if (!PERMITIR_INFERENCIA_POR_TEXTO || !attr.values?.length) return null;
  for (const v of attr.values) {
    const nomeNorm = normalizar(v.name);
    if (!nomeNorm || nomeNorm.length < 3) continue;
    if (textoProdutoNorm.includes(nomeNorm)) return v;
  }
  return null;
}

const principaisRecomendados = todosAtributos.filter(attr =>
  !obrigatorios.includes(attr) && (attr.tags?.catalog_required || (typeof attr.relevance === 'number' && attr.relevance <= RELEVANCE_THRESHOLD))
);
const outrosUteis = INCLUIR_ATRIBUTOS_EXTRAS
  ? todosAtributos.filter(attr => !obrigatorios.includes(attr) && !principaisRecomendados.includes(attr) && typeof attr.relevance === 'number')
  : [];

function chaveCombina(attrKeyNorm, sin) {
  const s = normalizar(sin);
  return attrKeyNorm === s || attrKeyNorm.includes(s) || s.includes(attrKeyNorm);
}

function buscarAtributoOrigem(attr) {
  const sinonimos = SINONIMOS[attr.id] || [];
  const nomeNorm = normalizar(attr.name);
  for (const sin of sinonimos) {
    const achou = amazonAttrs.find(a => chaveCombina(a._keyNorm, sin));
    if (achou) return achou;
  }
  return amazonAttrs.find(a => a._keyNorm && nomeNorm && (a._keyNorm.includes(nomeNorm) || nomeNorm.includes(a._keyNorm))) || null;
}

function casarComValorFixo(attr, valorTexto) {
  if (!attr.values?.length || !valorTexto) return null;
  const valorNorm = normalizar(valorTexto);
  let match = attr.values.find(v => normalizar(v.name) === valorNorm);
  if (!match) match = attr.values.find(v => normalizar(v.name).includes(valorNorm) || valorNorm.includes(normalizar(v.name)));
  return match || null;
}

function processarLista(lista, attributesPayload, pendentes, inferidos) {
  for (const attr of lista) {
    if (!isModificavel(attr)) continue;
    let valorEncontrado = attr.id === 'BRAND' ? dadosProduto.brand : (buscarAtributoOrigem(attr)?.value || null);
    let payloadItem = null;

    if (valorEncontrado) {
      if (attr.value_type === 'number_unit') {
        payloadItem = extrairNumberUnitDeTexto(attr, valorEncontrado);
        if (!payloadItem) {
          pendentes.push({ id: attr.id, name: attr.name, value_type: attr.value_type, allowed_units: attr.allowed_units || null, relevance: attr.relevance ?? null });
        }
      } else if (attr.value_type === 'list' || attr.value_type === 'boolean') {
        const valorFixo = casarComValorFixo(attr, valorEncontrado);
        if (valorFixo) payloadItem = { id: attr.id, value_id: valorFixo.id, value_name: valorFixo.name };
        else if (attr.tags?.allow_variations) payloadItem = { id: attr.id, value_name: String(valorEncontrado) };
        else pendentes.push({ id: attr.id, name: attr.name, value_type: attr.value_type, values: attr.values || null, relevance: attr.relevance ?? null });
      } else {
        payloadItem = { id: attr.id, value_name: String(valorEncontrado).slice(0, 255) };
      }
      if (payloadItem) attributesPayload.push(payloadItem);
      continue;
    }

    const inferidoTexto = inferirDeTexto(attr);
    if (inferidoTexto) {
      attributesPayload.push({ id: attr.id, value_id: inferidoTexto.id, value_name: inferidoTexto.name });
      inferidos.push({ id: attr.id, name: attr.name, value_name: inferidoTexto.name, confidence: 'media', fonte: 'texto_produto' });
      continue;
    }

    if (attr.id === 'ITEM_CONDITION' && ASSUMIR_PRODUTO_NOVO && attr.values?.length) {
      const novo = attr.values.find(v => /^(novo|new)$/i.test(normalizar(v.name)));
      if (novo) {
        attributesPayload.push({ id: attr.id, value_id: novo.id, value_name: novo.name });
        continue;
      }
    }

    if (attr.id === 'PACKAGING_TYPE') {
      const garrafa = (attr.values || []).find(v => /garrafa/i.test(v.name));
      if (garrafa && /garrafa|5\s*l|5l|5 litros/i.test(textoProdutoNorm)) {
        attributesPayload.push({ id: attr.id, value_id: garrafa.id, value_name: garrafa.name });
        continue;
      }
    }

    if (attr.id === 'DETERGENT_FORMAT') {
      const liquido = (attr.values || []).find(v => /liquido|líquido/i.test(v.name));
      if (liquido && /liquido|líquido|formula liquida/i.test(textoProdutoNorm)) {
        attributesPayload.push({ id: attr.id, value_id: liquido.id, value_name: liquido.name });
        continue;
      }
    }

    if (attr.value_type === 'number_unit') {
      const dimAttr = amazonAttrs.find(a => /dimens/i.test(a._keyNorm));
      if (dimAttr) {
        payloadItem = extrairNumberUnitDeTexto(attr, dimAttr.value);
        if (payloadItem) {
          attributesPayload.push(payloadItem);
          inferidos.push({ id: attr.id, name: attr.name, value_name: payloadItem.value_name, confidence: 'alta', fonte: 'dimensoes_scraping' });
          continue;
        }
      }
      const vol = parseVolume(dadosProduto.title_full + ' ' + dadosProduto.description);
      if (vol && attr.id === 'NET_VOLUME') {
        attributesPayload.push(montarNumberUnitPayload(attr.id, vol));
        inferidos.push({ id: attr.id, name: attr.name, value_name: vol.number + ' ' + vol.unit, confidence: 'media', fonte: 'titulo_volume' });
        continue;
      }
    }

    pendentes.push({ id: attr.id, name: attr.name, value_type: attr.value_type, allowed_units: attr.allowed_units || null, values: attr.values || null, relevance: attr.relevance ?? null });
  }
}

const attributesPayload = [];
const pendentes = [];
const principaisPendentes = [];
const outrosPendentes = [];
const inferidos = [];

processarLista(obrigatorios, attributesPayload, pendentes, inferidos);
processarLista(principaisRecomendados, attributesPayload, principaisPendentes, inferidos);
processarLista(outrosUteis, attributesPayload, outrosPendentes, inferidos);

pendentes.sort((a, b) => (a.relevance ?? 99) - (b.relevance ?? 99));
principaisPendentes.sort((a, b) => (a.relevance ?? 99) - (b.relevance ?? 99));

return [{
  json: {
    category_id: categoryId,
    category_name: categoryName,
    attributes: attributesPayload,
    attributes_pendentes: pendentes,
    attributes_principais_pendentes: principaisPendentes,
    attributes_extras_pendentes: outrosPendentes,
    attributes_inferidos: inferidos,
    _definicoes_atributos: todosAtributos,
    _scraping_indexado: amazonAttrs.map(a => ({ key: a.key, value: a.value })),
    completude: {
      obrigatorios_total: obrigatorios.length,
      obrigatorios_preenchidos: obrigatorios.length - pendentes.length,
      percentual_obrigatorios: obrigatorios.length ? Math.round(((obrigatorios.length - pendentes.length) / obrigatorios.length) * 100) : 100
    }
  }
}];

const user = $input.first().json;
const tags = user.tags || [];
return [{ json: { is_user_product_model: tags.includes('user_product_seller'), seller_id: user.id } }];

function gerarEAN13() {
  let base = '7';
  for (let i = 1; i < 12; i++) base += Math.floor(Math.random() * 10);
  let soma = 0;
  for (let i = 0; i < 12; i++) {
    const num = parseInt(base[i], 10);
    soma += (i % 2 === 0) ? num : num * 3;
  }
  const digito = (10 - (soma % 10)) % 10;
  return base + digito;
}

return [{ json: { ean: gerarEAN13(), _gtin_gerado: true } }];

function getNodeJson(nodeName) {
  try { return $(nodeName).first().json; }
  catch (e) { throw new Error('Node "' + nodeName + '" não foi executado nesta run.'); }
}

// --- Helpers de scraping (inline para n8n) ---
function normalizar(str) {
  return String(str || '').toLowerCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

const CHAVE_SCRAPING_PARA_ML = {
  aroma: ['FRAGRANCE', 'MAIN_AROMA'],
  'referencia do fabricante': ['MPN', 'MODEL', 'SELLER_SKU'],
  modelo: ['MODEL'],
  marca: ['BRAND'],
  fabricante: ['BRAND'],
  'dimensoes do produto': ['PACKAGE_LENGTH', 'PACKAGE_WIDTH', 'PACKAGE_HEIGHT', 'SELLER_PACKAGE_LENGTH', 'SELLER_PACKAGE_WIDTH', 'SELLER_PACKAGE_HEIGHT', 'PACKAGE_WEIGHT', 'SELLER_PACKAGE_WEIGHT', 'NET_WEIGHT'],
  'peso do item': ['NET_WEIGHT', 'PACKAGE_WEIGHT', 'SELLER_PACKAGE_WEIGHT'],
  peso: ['NET_WEIGHT', 'PACKAGE_WEIGHT', 'SELLER_PACKAGE_WEIGHT'],
  volume: ['NET_VOLUME'],
  capacidade: ['NET_VOLUME'],
  'usos especificos do produto': ['PRODUCT_USE', 'SPECIFIC_USES', 'IDEAL_USE'],
  'beneficios do produto': ['PRODUCT_BENEFITS', 'BENEFITS'],
  'tipo de embalagem': ['PACKAGING_TYPE'],
  formato: ['DETERGENT_FORMAT', 'SALE_FORMAT'],
  cor: ['COLOR', 'MAIN_COLOR'],
  material: ['MATERIAL', 'MAIN_MATERIAL'],
  linha: ['LINE'],
  ean: ['GTIN'],
  'codigo de barras': ['GTIN'],
  'numero de modelo': ['MODEL', 'MPN'],
  tamanho: ['SIZE', 'NET_VOLUME']
};

function indexarAtributosScraping(rawAttrs) {
  const porChave = new Map();
  const todos = [];
  for (const a of (rawAttrs || [])) {
    if (!a?.key) continue;
    const entry = { key: a.key, value: String(a.value || '').trim(), keyNorm: normalizar(a.key) };
    todos.push(entry);
    porChave.set(entry.keyNorm, entry);
    for (const [chave, ids] of Object.entries(CHAVE_SCRAPING_PARA_ML).sort((a, b) => b[0].length - a[0].length)) {
      if (entry.keyNorm.includes(chave)) {
        for (const id of ids) {
          if (!porChave.has('__ml__' + id)) porChave.set('__ml__' + id, entry);
        }
      }
    }
  }
  return { porChave, todos };
}

function parsePeso(texto) {
  const m = String(texto).match(/(\d+[.,]?\d*)\s*(quilogramas?|kg|gramas?|g)\b/i);
  if (!m) return null;
  let n = parseFloat(m[1].replace(',', '.'));
  if (/quilo|kg/i.test(m[2])) n = Math.round(n * 1000);
  return { number: n, unit: 'g' };
}

function parseVolume(texto) {
  const m = String(texto).match(/(\d+[.,]?\d*)\s*(litros?|l|ml|mililitros?)\b/i);
  if (!m) return null;
  const n = parseFloat(m[1].replace(',', '.'));
  if (/ml|mililitro/i.test(m[2])) return { number: n, unit: 'ml' };
  return { number: n, unit: 'L' };
}

function parseDimensoesCm(texto) {
  const m = String(texto).match(/(\d+[.,]?\d*)\s*x\s*(\d+[.,]?\d*)\s*x\s*(\d+[.,]?\d*)\s*cm/i);
  if (!m) return null;
  const nums = [m[1], m[2], m[3]].map(v => parseFloat(v.replace(',', '.')));
  nums.sort((a, b) => b - a);
  return { length: nums[0], width: nums[1], height: nums[2], unit: 'cm' };
}

function extrairDimensoesScraping(dadosProduto, scraping) {
  const textos = [];
  for (const a of scraping.todos) {
    if (/dimens|peso|embalagem|tamanho/i.test(a.key)) textos.push(a.value);
  }
  textos.push(dadosProduto.title_full, dadosProduto.description);
  let dims = null, peso = null, volume = null;
  for (const t of textos.filter(Boolean)) {
    if (!dims) dims = parseDimensoesCm(t);
    if (!peso) peso = parsePeso(t);
    if (!volume) volume = parseVolume(t);
  }
  if (!volume) volume = parseVolume((dadosProduto.title_full || '') + ' ' + (dadosProduto.description || ''));
  return { dims, peso, volume };
}

function buscarValorPorChaveScraping(mlId, scraping) {
  const direto = scraping.porChave.get('__ml__' + mlId);
  if (direto) return direto.value;
  for (const [chave, ids] of Object.entries(CHAVE_SCRAPING_PARA_ML)) {
    if (!ids.includes(mlId)) continue;
    const achou = scraping.porChave.get(chave) || scraping.todos.find(a => a.keyNorm.includes(chave));
    if (achou) return achou.value;
  }
  return null;
}

function casarValorLista(valorTexto, attr) {
  if (!attr?.values?.length || !valorTexto) return null;
  const vn = normalizar(valorTexto);
  let m = attr.values.find(v => normalizar(v.name) === vn);
  if (!m) m = attr.values.find(v => vn.includes(normalizar(v.name)) || normalizar(v.name).includes(vn));
  return m ? { value_id: m.id, value_name: m.name } : null;
}

function montarNumberUnit(id, number, unit, allowedUnits) {
  let u = unit;
  if (allowedUnits?.length) {
    const match = allowedUnits.find(x => normalizar(x.id) === normalizar(unit) || normalizar(x.name) === normalizar(unit));
    u = match ? match.id : allowedUnits[0].id;
  }
  const n = Number(number);
  return { id, value_name: n + ' ' + u, value_struct: { number: n, unit: u } };
}

// --- Tendências ML (SEO por categoria) ---
const RUIDO_TRENDS = /^(acessar minha conta|minha conta|login|entrar)$/i;
const MARCAS_GENERICAS_TRENDS = /^(nike|adidas|apple|samsung|iphone|xiaomi|lacoste|hering|oakley|revlon|lancome)$/i;

function extrairMsgErro(e) {
  if (!e) return 'Tendências não disponíveis nesta run';
  if (typeof e === 'string') return e;
  try { return String(e.message || e); } catch (_) { return 'Tendências não disponíveis nesta run'; }
}

function normalizarListaTrends(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  if (Array.isArray(raw.trends)) return raw.trends;
  if (raw.keyword) return [raw];
  return [];
}

function lerTrendsDisponiveis() {
  // 1) Merge → Montar Payload ($input traz trends do Agregar Tendências ML1)
  for (const item of $input.all()) {
    const lista = normalizarListaTrends(item.json);
    if (lista.length) return { lista, origem: 'merge_input' };
  }

  // 2) Node agregador (mesma execução, após HTTP)
  try {
    const agg = $('Agregar Tendências ML1').first().json;
    const lista = normalizarListaTrends(agg);
    if (lista.length) return { lista, origem: 'agregar_node' };
  } catch (_) {}

  // 3) HTTP direto (50 itens separados)
  try {
    const items = $('Buscar Tendências ML1').all();
    if (items?.length) {
      if (items.length === 1 && Array.isArray(items[0].json)) {
        return { lista: items[0].json, origem: 'http_array' };
      }
      if (items.every(i => i.json?.keyword)) {
        return { lista: items.map(i => i.json), origem: 'http_items' };
      }
      const lista = items.map(i => i.json).filter(j => j?.keyword);
      if (lista.length) return { lista, origem: 'http_items' };
    }
  } catch (_) {}

  return { lista: [], origem: 'nenhuma' };
}

function parseTrendsResponse(raw) {
  let arr = [];
  if (Array.isArray(raw)) arr = raw;
  else if (Array.isArray(raw?.trends)) arr = raw.trends;
  else if (raw?.keyword) arr = [raw];
  return arr.map((item, idx) => ({
    keyword: String(item?.keyword || item || '').trim(),
    url: item?.url || null,
    tier: idx < 10 ? 'crescimento' : idx < 30 ? 'desejadas' : 'populares',
    rank: idx + 1
  })).filter(t => t.keyword.length >= 3 && !RUIDO_TRENDS.test(t.keyword));
}

function tokenizarTrends(texto) {
  return normalizar(texto).split(' ').filter(w => w.length > 2);
}

function textoContemKeyword(textoNorm, keyword) {
  const k = normalizar(keyword);
  if (!k) return false;
  if (textoNorm.includes(k)) return true;
  const partes = k.split(' ').filter(p => p.length > 3);
  return partes.length > 0 && partes.every(p => textoNorm.includes(p));
}

function scoreKeywordTrend(trend, ctx) {
  const kw = trend.keyword;
  const kwNorm = normalizar(kw);
  let score = 0;
  const kwTokens = tokenizarTrends(kw);
  score += kwTokens.filter(t => ctx.tokens.has(t)).length * 4;
  if (ctx.categoryNorm && (kwNorm.includes(ctx.categoryNorm) || ctx.categoryNorm.includes(kwNorm))) score += 3;
  if (trend.tier === 'crescimento') score += 3;
  else if (trend.tier === 'desejadas') score += 2;
  else score += 1;
  if (kwTokens.length >= 2) score += 2;
  if (MARCAS_GENERICAS_TRENDS.test(kw)) score -= 5;
  if (kwTokens.filter(t => ctx.tokens.has(t)).length === 0 &&
      !ctx.categoryNorm.split(' ').some(c => c.length > 3 && kwNorm.includes(c))) score -= 2;
  return score;
}

function selecionarKeywordsTrends(trends, produto, categoria, max) {
  max = max || 8;
  const textoBase = [produto.title_full, produto.title, produto.description, produto.brand, categoria?.category_name].filter(Boolean).join(' ');
  const ctx = { tokens: new Set(tokenizarTrends(textoBase)), categoryNorm: normalizar(categoria?.category_name || '') };
  const vistos = new Set();
  return trends.map(t => ({ ...t, score: scoreKeywordTrend(t, ctx) }))
    .filter(t => t.score >= 2)
    .sort((a, b) => b.score - a.score || a.rank - b.rank)
    .filter(t => { const k = normalizar(t.keyword); if (vistos.has(k)) return false; vistos.add(k); return true; })
    .slice(0, max);
}

function truncarTituloSeo(titulo, max) {
  const t = String(titulo || '').trim();
  if (t.length <= max) return t;
  let cortado = t.slice(0, max);
  const lastSpace = cortado.lastIndexOf(' ');
  if (lastSpace > max * 0.5) cortado = cortado.slice(0, lastSpace);
  return cortado.trim();
}

function otimizarTituloComTrends(tituloBase, keywords, maxLen) {
  let titulo = String(tituloBase || '').trim();
  if (!keywords.length) return truncarTituloSeo(titulo, maxLen);
  let tituloNorm = normalizar(titulo);
  for (const { keyword } of keywords.slice(0, 5)) {
    if (titulo.length >= maxLen) break;
    if (textoContemKeyword(tituloNorm, keyword)) continue;
    const candidato = titulo + ' ' + keyword;
    if (candidato.length <= maxLen) {
      titulo = candidato;
      tituloNorm = normalizar(titulo);
    }
  }
  return truncarTituloSeo(titulo, maxLen);
}

function otimizarModeloComTrends(valorAtual, keywords, maxLen) {
  maxLen = maxLen || 255;
  const base = String(valorAtual || '').trim();
  const baseNorm = normalizar(base);
  const extras = [];
  for (const { keyword } of keywords) {
    if (extras.length >= 5) break;
    if (!textoContemKeyword(baseNorm, keyword) && !extras.some(e => normalizar(e) === normalizar(keyword))) {
      extras.push(keyword);
    }
  }
  if (!extras.length) return base.slice(0, maxLen);
  if (!base || /^padrao$/i.test(baseNorm)) return extras.join(' | ').slice(0, maxLen).trim();
  return (base + ' | ' + extras.join(' | ')).slice(0, maxLen).trim();
}

function otimizarDescricaoComTrends(descricao, keywords, categoriaNome) {
  const texto = String(descricao || '').trim();
  if (!texto || !keywords.length) return texto;
  const textoNorm = normalizar(texto);
  const novas = keywords.filter(k => !textoContemKeyword(textoNorm, k.keyword)).slice(0, 5);
  if (!novas.length) return texto;
  const termos = novas.map(k => k.keyword);
  const sentencas = texto.split(/(?<=[.!?])\s+/).filter(Boolean);
  if (sentencas.length >= 2 && termos[0]) {
    const alvo = Math.min(1, sentencas.length - 1);
    if (!textoContemKeyword(normalizar(sentencas[alvo]), termos[0])) {
      sentencas[alvo] = sentencas[alvo].replace(/[.!?]\s*$/, '') + ', uma excelente opção para quem pesquisa por ' + termos[0] + '.';
    }
  }
  if (termos.length > 1) {
    const fechamento = 'Produto alinhado às tendências de busca em ' + (categoriaNome || 'esta categoria') +
      ', incluindo termos como ' + termos.slice(0, 3).join(', ') + '.';
    if (!textoContemKeyword(normalizar(sentencas.join(' ')), termos.slice(0, 3).join(', '))) {
      sentencas.push(fechamento);
    }
  }
  return sentencas.join(' ').trim().slice(0, 5000);
}

function isModificavelSaleTerm(id) {
  const def = saleTermsPorId.get(id);
  if (!def) return false;
  if (def.tags?.read_only) return false;
  return true;
}

function campoUiFromDef(def, grupo) {
  if (!def) return null;
  return {
    id: def.id,
    nome: def.name,
    grupo,
    value_type: def.value_type,
    obrigatorio: !!(def.tags?.required || def.tags?.conditional_required || def.tags?.new_required || def.relevance === 1),
    values: def.values || null,
    allowed_units: def.allowed_units || null,
    preenchido: false,
    valor_atual: null,
    destino_payload: grupo === 'garantia' || grupo === 'limite_unidades' ? 'sale_terms' : 'attributes'
  };
}

function campoUiComValor(def, grupo) {
  const campo = campoUiFromDef(def, grupo);
  if (!campo) return null;
  const atual = attributesMap.get(def.id);
  campo.preenchido = !!atual;
  campo.valor_atual = atual || null;
  if (atual?.value_name) campo.sugestao = atual.value_name;
  return campo;
}

