function isModificavelAttr(id) {
  if (NUNCA_INVENTAR.has(id)) return false;
  const def = defsPorId.get(id);
  if (def?.tags?.read_only && !id.startsWith('PACKAGE_') && !id.startsWith('SELLER_PACKAGE_')) return false;
