}

function attrValido(attr) {
  if (!attr?.id) return false;
  if (attr.value_struct?.number != null && attr.value_struct?.unit) return true;
  if (attr.value_id != null) return true;
  const vn = String(attr.value_name || '').trim();
  return vn.length > 0 && vn.toLowerCase() !== 'não especificado' && vn !== '0 h';
}

const attributesMap = new Map();
const preenchidosScraping = [];
const preenchidosInteligente = [];
const preenchidosComFicticio = [];
const preenchidosTrends = [];
const aindaPendentes = [];

function setAttribute(attr, forcar, fonte) {
  if (!attr?.id) return;
  if (!(forcar || isModificavelAttr(attr.id))) return;
  if (!attrValido(attr)) return;
  if (attributesMap.has(attr.id) && fonte !== 'scraping' && fonte !== 'trends') return;
  attributesMap.set(attr.id, attr);
  if (fonte === 'scraping') preenchidosScraping.push({ id: attr.id, valor: attr.value_name || attr.value_struct });
  if (fonte === 'trends') preenchidosTrends.push({ id: attr.id, valor: attr.value_name });
}

