// 2) Resolver atributos da categoria a partir do scraping
function resolverDeScraping(def) {
  if (!def?.id || !isModificavelAttr(def.id)) return null;
  const id = def.id;
  let valorTexto = buscarValorPorChaveScraping(id, scraping);

  if (!valorTexto && id === 'BRAND') valorTexto = dadosProduto.brand;
  if (!valorTexto && id === 'MANUAL_TITLE') valorTexto = dadosProduto.title_full || dadosProduto.title;
  if (!valorTexto && id === 'SELLER_SKU') valorTexto = buscarValorPorChaveScraping('MPN', scraping) || dadosProduto.asin;
  if (!valorTexto && (id === 'MPN' || id === 'MODEL')) valorTexto = buscarValorPorChaveScraping(id, scraping);

  if (!valorTexto && id === 'DETERGENT_FORMAT' && /liquido|líquido/i.test(textoRico)) valorTexto = 'Líquido';
  if (!valorTexto && id === 'PACKAGING_TYPE' && /garrafa|5\s*l|5l|5 litros/i.test(textoRico)) valorTexto = 'Garrafa';
  if (!valorTexto && id === 'LINE' && dadosProduto.brand) valorTexto = dadosProduto.brand;

  if (!valorTexto) return null;

  if (def.value_type === 'number_unit') {
    if (/length|comprimento/i.test(id) && medidas.dims) return montarNumberUnit(id, medidas.dims.length, 'cm', def.allowed_units);
    if (/width|largura/i.test(id) && medidas.dims) return montarNumberUnit(id, medidas.dims.width, 'cm', def.allowed_units);
    if (/height|altura/i.test(id) && medidas.dims) return montarNumberUnit(id, medidas.dims.height, 'cm', def.allowed_units);
    if (/weight|peso/i.test(id) && medidas.peso) return montarNumberUnit(id, medidas.peso.number, medidas.peso.unit, def.allowed_units);
    if (/volume/i.test(id) && medidas.volume) return montarNumberUnit(id, medidas.volume.number, medidas.volume.unit, def.allowed_units);
    const m = String(valorTexto).match(/(\d+[.,]?\d*)\s*([a-zA-Z]+)/);
    if (m) return montarNumberUnit(id, parseFloat(m[1].replace(',', '.')), m[2], def.allowed_units);
    return null;
  }

  if (def.value_type === 'list' || def.value_type === 'boolean') {
    const casado = casarValorLista(valorTexto, def);
    if (casado) return { id, ...casado };
    if (def.tags?.allow_variations) return { id, value_name: valorTexto };
    for (const v of (def.values || [])) {
      if (v.name && textoRico.includes(normalizar(v.name))) return { id, value_id: v.id, value_name: v.name };
    }
    return null;
  }

  if (def.value_type === 'number') {
    if (['UNITS_PER_PACK', 'UNITS_PER_PACKAGE'].includes(id)) return { id, value_name: '1' };
    const m = String(valorTexto).match(/\d+[.,]?\d*/);
    return m ? { id, value_name: m[0].replace(',', '.') } : null;
  }

  return { id, value_name: String(valorTexto).slice(0, 255) };
}

for (const def of (atributosInfo._definicoes_atributos || [])) {
  if (attributesMap.has(def.id)) continue;
  const resolvido = resolverDeScraping(def);
  if (resolvido) setAttribute(resolvido, def.id.startsWith('PACKAGE_'), 'scraping');
}

// 3) Booleanos inferidos do texto (benefícios, usos)
const booleanInferencias = [
