  if (!patterns.some(p => p.test(textoRico))) continue;
  const def = defsPorId.get(id);
  const sim = (def.values || []).find(v => /^sim$/i.test(v.name));
  if (sim) setAttribute({ id, value_id: sim.id, value_name: sim.name }, false, 'scraping');
}

// 4) Preencher pendentes (inteligente + fallback v2.3)
function buscarValorInteligente(pendente) {
  const doScraping = resolverDeScraping(pendente);
  if (doScraping) return doScraping;
  if (pendente.value_type === 'list' || pendente.value_type === 'boolean') {
    const opcao = (pendente.values || []).find(v => v.name && textoRico.includes(v.name.toLowerCase()));
    return opcao ? { value_id: opcao.id, value_name: opcao.name } : null;
  }
  if (pendente.value_type === 'number_unit' && PACKAGE_DEFAULTS[pendente.id]) {
    return montarNumberUnit(pendente.id, PACKAGE_DEFAULTS[pendente.id].number, PACKAGE_DEFAULTS[pendente.id].unit, pendente.allowed_units);
  }
  if (pendente.value_type === 'number' && ['UNITS_PER_PACK', 'UNITS_PER_PACKAGE'].includes(pendente.id)) {
    return { value_name: '1' };
  }
  if (pendente.value_type === 'string') {
    if (pendente.id === 'SELLER_SKU') return { value_name: buscarValorPorChaveScraping('MPN', scraping) || dadosProduto.asin || ('SKU-' + (dadosProduto._origem || 'ml').toUpperCase()) };
    if (pendente.id === 'LINE' && dadosProduto.brand) return { value_name: dadosProduto.brand };
    if (pendente.id === 'MODEL' || pendente.id === 'MPN') {
      const ref = buscarValorPorChaveScraping(pendente.id, scraping);
      if (ref) return { value_name: ref };
    }
    if (pendente.id === 'MANUAL_TITLE') return { value_name: dadosProduto.title_full || dadosProduto.title };
  }
  return null;
}

function gerarValorFicticio(pendente) {
  if (NUNCA_INVENTAR.has(pendente.id) || REGULATORIOS.has(pendente.id)) return null;
  if (pendente.value_type === 'number_unit' && PACKAGE_DEFAULTS[pendente.id]) {
    return montarNumberUnit(pendente.id, PACKAGE_DEFAULTS[pendente.id].number, PACKAGE_DEFAULTS[pendente.id].unit, pendente.allowed_units);
  }
  if (pendente.value_type === 'number' && ['UNITS_PER_PACK', 'UNITS_PER_PACKAGE'].includes(pendente.id)) return { value_name: '1' };
  if (pendente.value_type === 'string' && pendente.id === 'SELLER_SKU') {
    return { value_name: buscarValorPorChaveScraping('MPN', scraping) || dadosProduto.asin || ('SKU-' + (dadosProduto._origem || 'ML').toUpperCase()) };
  }
  if (pendente.value_type === 'list' && pendente.id === 'PACKAGING_TYPE') {
    const garrafa = (pendente.values || []).find(v => /garrafa/i.test(v.name));
    if (garrafa) return { value_id: garrafa.id, value_name: garrafa.name };
  }
  if (pendente.value_type === 'string') {
    if (pendente.id === 'LINE' && dadosProduto.brand) return { value_name: dadosProduto.brand };
    if (pendente.id === 'MODEL') {
      const ref = buscarValorPorChaveScraping('MPN', scraping);
      if (ref) return { value_name: ref };
    }
    if (pendente.id === 'MANUAL_TITLE') return { value_name: dadosProduto.title_full || dadosProduto.title };
  }
  return null;
}

function resolverPendentes(lista) {
  for (const pendente of lista) {
    if (pendente.id === 'GTIN') {
      setAttribute({ id: 'GTIN', value_name: eanGerado }, false, 'ean');
      preenchidosComFicticio.push({ id: 'GTIN', fonte: 'ean_gerado' });
      continue;
    }
    if (pendente.id === 'EMPTY_GTIN_REASON') continue;
    if (REGULATORIOS.has(pendente.id)) continue;

    const inteligente = buscarValorInteligente(pendente);
    if (inteligente) {
      setAttribute({ id: pendente.id, ...inteligente }, false, 'inteligente');
      preenchidosInteligente.push({ id: pendente.id, valor: inteligente });
      continue;
    }
    const ficticio = gerarValorFicticio(pendente);
    if (ficticio) {
      setAttribute({ id: pendente.id, ...ficticio }, false, 'fallback');
      preenchidosComFicticio.push({ id: pendente.id, valor: ficticio });
    } else if (pendente.relevance === 1) {
      aindaPendentes.push(pendente);
    }
  }
}

resolverPendentes(atributosInfo.attributes_pendentes || []);
resolverPendentes(atributosInfo.attributes_principais_pendentes || []);

// Embalagens fallback só se scraping não trouxe
for (const [id, struct] of Object.entries(PACKAGE_DEFAULTS)) {
  if (!attributesMap.has(id) && defsPorId.has(id)) {
    setAttribute(montarNumberUnit(id, struct.number, struct.unit, defsPorId.get(id)?.allowed_units), id.startsWith('PACKAGE_'), 'fallback');
    preenchidosComFicticio.push({ id, fonte: 'fallback_embalagem' });
  }
}

if (!attributesMap.has('SELLER_SKU') && defsPorId.has('SELLER_SKU')) {
  setAttribute({ id: 'SELLER_SKU', value_name: buscarValorPorChaveScraping('MPN', scraping) || dadosProduto.asin || ('SKU-' + (dadosProduto._origem || 'ML').toUpperCase()) }, false, 'fallback');
}

const saleFormat = attributesMap.get('SALE_FORMAT');
if (saleFormat && /unidade/i.test(saleFormat.value_name || '')) {
  if (!attributesMap.has('UNITS_PER_PACK')) setAttribute({ id: 'UNITS_PER_PACK', value_name: '1' }, false, 'regra_ml');
  if (!attributesMap.has('UNITS_PER_PACKAGE')) setAttribute({ id: 'UNITS_PER_PACKAGE', value_name: '1' }, false, 'regra_ml');
}

if (attributesMap.has('GTIN')) attributesMap.delete('EMPTY_GTIN_REASON');

// Trends somente em: título (payload), descrição e MODEL
if (trendsKeywords.length && defsPorId.has('MODEL')) {
  const atualModel = attributesMap.get('MODEL');
  const baseModel = atualModel?.value_name
    || buscarValorPorChaveScraping('MODEL', scraping)
    || buscarValorPorChaveScraping('MPN', scraping)
    || '';
  const modeloOtimizado = otimizarModeloComTrends(baseModel, trendsKeywords, 255);
  if (modeloOtimizado) setAttribute({ id: 'MODEL', value_name: modeloOtimizado }, true, 'trends');
}

const sale_terms = [];
const saleTermsPendentes = [];
const warrantyTypeDef = saleTermsPorId.get('WARRANTY_TYPE');
const warrantyTimeDef = saleTermsPorId.get('WARRANTY_TIME');

for (const def of saleTermsDefs) {
  if (!isModificavelSaleTerm(def.id)) continue;
  if (def.id === 'WARRANTY_TYPE') {
    const sem = (def.values || []).find(v => /sem garantia|sin garantía/i.test(v.name));
    if (sem) sale_terms.push({ id: def.id, value_id: sem.id, value_name: sem.name });
    else saleTermsPendentes.push(campoUiFromDef(def, 'garantia'));
    continue;
  }
  if (def.id === 'WARRANTY_TIME') {
    const wt = sale_terms.find(t => t.id === 'WARRANTY_TYPE');
    if (wt && !/sem garantia|sin garantía/i.test(wt.value_name || '')) {
      const unidade = def.allowed_units?.[0]?.id || 'dias';
      sale_terms.push({ id: def.id, value_name: '90 ' + unidade, value_struct: { number: 90, unit: unidade } });
    } else if (!wt) saleTermsPendentes.push(campoUiFromDef(def, 'garantia'));
    continue;
  }
  if (def.id === 'PURCHASE_MAX_QUANTITY') {
    saleTermsPendentes.push({ ...campoUiFromDef(def, 'limite_unidades'), sugestao: '10' });
  }
}

const PACKAGE_IDS = ['PACKAGE_HEIGHT', 'PACKAGE_WIDTH', 'PACKAGE_LENGTH', 'PACKAGE_WEIGHT'];
const SELLER_PACKAGE_IDS = ['SELLER_PACKAGE_HEIGHT', 'SELLER_PACKAGE_WIDTH', 'SELLER_PACKAGE_LENGTH', 'SELLER_PACKAGE_WEIGHT'];
const FORMATO_VENDA_IDS = ['SALE_FORMAT', 'UNITS_PER_PACK', 'UNITS_PER_PACKAGE', 'NET_VOLUME', 'NET_WEIGHT'];
const CARACTERISTICAS_IDS = ['SELLER_SKU', 'GTIN', 'MPN', 'BRAND', 'LINE', 'MODEL', 'FRAGRANCE', 'MAIN_AROMA', 'DETERGENT_FORMAT', 'PACKAGING_TYPE', 'IS_STAIN_REMOVER', 'IS_SUITABLE_FOR_HAND_WASHING', 'IS_ANTIBACTERIAL', 'MANUAL_TITLE'];

const embalagemFabrica = PACKAGE_IDS.map(id => {
  const def = defsPorId.get(id);
  const campo = campoUiComValor(def, 'embalagem_envio');
  if (campo) campo.destino_payload = 'attributes';
  return campo;
}).filter(Boolean);

const embalagemEnvio = SELLER_PACKAGE_IDS.map(id => campoUiComValor(defsPorId.get(id), 'embalagem_envio')).filter(Boolean);

const formatoVendaCampos = FORMATO_VENDA_IDS.map(id => campoUiComValor(defsPorId.get(id), 'formato_venda')).filter(Boolean);

const secundariasDefs = (atributosInfo._definicoes_atributos || []).filter(d => {
  if (!isModificavelAttr(d.id) || REGULATORIOS.has(d.id)) return false;
  if (PACKAGE_IDS.includes(d.id) || SELLER_PACKAGE_IDS.includes(d.id) || FORMATO_VENDA_IDS.includes(d.id)) return false;
  if (CARACTERISTICAS_IDS.includes(d.id)) return true;
  return typeof d.relevance === 'number' && d.relevance >= 2 && d.relevance <= 4;
});

const caracteristicasCampos = secundariasDefs.map(d => campoUiComValor(d, 'caracteristicas_secundarias')).filter(Boolean);
const secundariasPreenchidas = caracteristicasCampos.filter(c => c.preenchido).length;

const regulatoriosPendentes = [...aindaPendentes, ...(atributosInfo.attributes_pendentes || [])]
  .filter(p => REGULATORIOS.has(p.id))
  .map(p => campoUiComValor(defsPorId.get(p.id) || p, 'info_regulatoria'))
  .filter(Boolean);

const _ihub_ui = {
  versao: '1.0',
  category_id: categoria.category_id || atributosInfo.category_id,
  category_name: categoria.category_name || atributosInfo.category_name,
  secoes: [
    {
      id: 'embalagem_fabrica',
      titulo: 'Embalagem de fábrica',
      status: embalagemFabrica.every(c => c.preenchido) ? 'ok' : 'somente_leitura',
      mensagem: 'Medidas extraídas do scraping (PACKAGE_*). O ML pode ajustar no catálogo.',
      campos: embalagemFabrica
    },
    {
      id: 'embalagem_envio',
      titulo: 'Embalagem de envio',
      status: embalagemEnvio.every(c => c.preenchido) ? 'ok' : 'pendente',
      mensagem: 'Dimensões do pacote que você envia (SELLER_PACKAGE_*).',
      campos: embalagemEnvio
    },
    {
      id: 'formato_venda',
      titulo: 'Formato de venda',
      status: formatoVendaCampos.filter(c => c.obrigatorio && !c.preenchido).length === 0 ? 'ok' : 'pendente',
      campos: formatoVendaCampos
    },
    {
      id: 'caracteristicas_secundarias',
      titulo: 'Características do produto',
      status: caracteristicasCampos.filter(c => c.obrigatorio && !c.preenchido).length === 0 ? 'ok' : 'pendente',
      completas: secundariasPreenchidas,
      total: caracteristicasCampos.length,
      mensagem: 'SKU, aroma, marca, tipo de embalagem e demais atributos do ML.',
      campos: caracteristicasCampos
    },
    {
