      titulo: 'Informação regulatória',
      status: regulatoriosPendentes.filter(c => c.obrigatorio && !c.preenchido).length === 0 ? 'ok' : 'pendente',
      mensagem: 'Dados exigidos por normas (Anvisa, etc.).',
      campos: regulatoriosPendentes
    },
    {
      id: 'retirada_pessoal',
      titulo: 'Retirar pessoalmente',
      status: 'ok',
      valor_atual: false,
      editavel: true,
      campo: { id: 'shipping.local_pick_up', nome: 'Oferece retirada pessoal', grupo: 'condicoes_venda', value_type: 'boolean', preenchido: true, valor_atual: false, destino_payload: 'shipping' }
    },
    {
      id: 'descricao',
