      titulo: 'Condição',
      status: 'ok',
      valor_atual: 'Novo'
    },
    {
      id: 'garantia',
      titulo: 'Garantia',
      status: sale_terms.find(t => t.id === 'WARRANTY_TYPE') ? 'ok' : 'pendente',
      campos: saleTermsPendentes.filter(c => c.grupo === 'garantia'),
      opcoes_tipicas: ['Garantia do vendedor', 'Garantia de fábrica', 'Sem garantia']
    }
  ],
  campos_editaveis: [
    ...embalagemEnvio,
    ...formatoVendaCampos,
    ...caracteristicasCampos,
    ...regulatoriosPendentes.filter(c => !c.preenchido),
    ...saleTermsPendentes
  ].filter(Boolean)
};

const shipping = { mode: 'me2', local_pick_up: false, free_shipping: false };
const bloqueios = [...(dadosProduto._avisos || [])];
const secoesPendentes = _ihub_ui.secoes.filter(s => s.status === 'pendente').map(s => s.id);
if (secoesPendentes.length) bloqueios.push('Seções para revisar no iHub: ' + secoesPendentes.join(', '));
regulatoriosPendentes.filter(c => c.obrigatorio && !c.preenchido).forEach(c => {
  bloqueios.push('Informação regulatória pendente: ' + c.id + ' (' + c.nome + ')');
});
const attributes = Array.from(attributesMap.values());

const payload = {
