  }
}];

const webhookBody = $('Webhook - Recebe Link Amazon').first().json.body || {};
const jobId = webhookBody.jobId;
const draft = $('Montar Payload ML1').first().json;
const MARKETPLACE_ID = webhookBody.marketplaceId || 'A2Q3Y263D00KWC';

function attrLocale(value) {
  return [{ value, marketplace_id: MARKETPLACE_ID }];
}

const payload = draft.payload || {};
const attrsMl = Array.isArray(payload.attributes) ? payload.attributes : [];
const findAttr = (id) => attrsMl.find(a => a.id === id);

const title = (payload.family_name || '').trim() || 'Produto';
const brand = (findAttr('BRAND')?.value_name || '').trim() || undefined;
const sellerSkuRaw = (findAttr('SELLER_SKU')?.value_name || '').trim();
const asin = draft._asin || null;
const sellerSku = sellerSkuRaw || (asin ? ('SKU-AMZ-' + asin) : ('SKU-' + Date.now()));
const price = typeof payload.price === 'number' ? payload.price : Number(payload.price) || 0;
const qty = typeof payload.available_quantity === 'number' ? payload.available_quantity : 1;
const description = draft._description || '';
const pictures = Array.isArray(payload.pictures) ? payload.pictures.map(p => p.source).filter(Boolean) : [];

const titleL = title.toLowerCase();
let productType = 'PRODUCT';
if (/t[eê]nis|sapato|bota|chinelo|sand[aá]lia|sneaker|shoe/.test(titleL)) productType = 'SHOES';
else if (/camis|camiseta|cal[cç]a|vestido|jaqueta|roupa|shorts|bermuda/.test(titleL)) productType = 'SHIRT';
else if (/necessaire|cosmetic|maquiagem|toiletry|makeup|estojo|organizador de bolsa|organizador interno/.test(titleL)) productType = 'COSMETIC_CASE';
else if (/mochila|backpack/.test(titleL)) productType = 'BACKPACK';
else if (/mala\b|luggage|suitcase|bagagem/.test(titleL)) productType = 'LUGGAGE';
else if (/bolsa|bag|carteira|wallet|pochete|shoulder bag/.test(titleL)) productType = 'BAG';

const attributes = {
  item_name: attrLocale(title),
  condition_type: attrLocale(payload.condition === 'used' ? 'used_like_new' : 'new_new'),
  fulfillment_availability: [
    { fulfillment_channel_code: 'DEFAULT', quantity: qty }
  ],
  purchasable_offer: [
    {
      marketplace_id: MARKETPLACE_ID,
      currency: 'BRL',
      our_price: [{ schedule: [{ value_with_tax: price > 0 ? price : 1 }] }]
    }
  ]
};
if (brand) attributes.brand = attrLocale(brand);
if (description) attributes.product_description = attrLocale(description);
if (pictures[0]) {
  attributes.main_product_image_locator = [
    { media_location: pictures[0], marketplace_id: MARKETPLACE_ID }
  ];
}
for (let i = 1; i < Math.min(pictures.length, 9); i++) {
  attributes['other_product_image_locator_' + i] = [
    { media_location: pictures[i], marketplace_id: MARKETPLACE_ID }
  ];
}
const gtin = draft._gtin || findAttr('GTIN')?.value_name;
if (gtin) {
  attributes.externally_assigned_product_identifier = [
    { type: 'ean', value: String(gtin), marketplace_id: MARKETPLACE_ID }
  ];
}

const needsTypeConfirm = productType === 'PRODUCT';
const amazonDraft = {
  platform: 'amazon',
  payload: {
    sellerSku,
    productType,
    requirements: 'LISTING',
    attributes
  },
  _marketplace_id: MARKETPLACE_ID,
  _asin: asin,
  _description: description,
  _pronto_para_publicar: !needsTypeConfirm && price > 0 && pictures.length > 0,
  _product_type_sugerido: productType,
  _bloqueios: needsTypeConfirm ? ['Confirme o productType Amazon antes de publicar'] : [],
  _origem: draft._origem,
  _ihub_ui: {
    secoes: [
      {
        id: 'amazon_basico',
        titulo: 'Amazon — publicação SP-API',
        status: needsTypeConfirm ? 'pendente' : 'completo',
        campos: [
          {
            id: 'productType',
            label: 'Product type',
            obrigatorio: true,
            destino_payload: 'attributes',
            tipo: 'string',
            valor: productType,
            hint: 'Ex.: COSMETIC_CASE, BAG, SHOES — deve existir no catálogo Amazon BR'
          },
          {
            id: 'sellerSku',
            label: 'Seller SKU',
            obrigatorio: true,
            destino_payload: 'attributes',
            tipo: 'string',
            valor: sellerSku
          }
        ]
      }
    ],
    campos_editaveis: []
  }
};

const status = amazonDraft._pronto_para_publicar ? 'completed' : 'needs_review';

return [{
  json: {
    jobId,
    status,
    targetPlatform: 'amazon',
    draft: amazonDraft,
    error: null
  }
}];

const items = $input.all();
const trends = items.map(i => i.json).filter(j => j && j.keyword);
return [{ json: { trends, count: trends.length } }];
